const slugOf = name => name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
// Each agent has a distinct evidence trigger, conditional branch and minimal review state.
const agent = (name, index, trigger, extra, branch, memory, schedule) => {
  const w=workflows[index];
  return {name,job:w.job,sector:w.sector,workflow:slugOf(w.name),need:w.need+' Include the previous review when available.',deliverable:w.deliverable,acceptance:w.acceptance,trigger,extra,branch:`Run ${slugOf(w.name)} for changed evidence or a due review. ${branch}`,memory,schedule:schedule+' Installation does not create a schedule.'};
};
